INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(22007085, 'Starry Knight Balefire', '神圣篝火', '聖なる篝火', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「圣夜骑士」怪兽或者龙族·光属性·7星怪兽加入手卡。对方场上有暗属性怪兽存在，自己场上没有怪兽存在的场合，可以再从手卡把1只龙族·光属性·7星怪兽特殊召唤。'),
(58374502, 'Starry Knight Blast', '神圣煌炎', '聖なる煌炎', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方把魔法·陷阱·怪兽的效果发动时，让自己场上1只龙族·光属性·7星怪兽回到持有者手卡才能发动。那个效果无效并破坏。'),
(85590798, 'Starry Knight Ceremony', '神圣降诞', '聖なる降誕', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己主要阶段才能发动。手卡1只天使族·光属性怪兽给对方观看，从卡组把1只龙族·光属性·7星怪兽加入手卡。那之后，给人观看的怪兽回到卡组最下面。 ②：对方把魔法·陷阱·怪兽的效果发动的场合才能发动。从手卡把1只龙族·光属性·7星怪兽特殊召唤。'),
(27036706, 'Starry Knight Ciel', '圣夜骑士团·西耶勒', 'ホーリーナイツ・シエル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，让「圣夜骑士团·西耶勒」以外的自己场上1只「圣夜骑士」怪兽或者龙族·光属性·7星怪兽回到持有者手卡才能发动。这张卡特殊召唤。 ②：自己场上没有怪兽存在的场合，把墓地的这张卡除外才能发动。从手卡把1只龙族·光属性·7星怪兽特殊召唤。'),
(86613346, 'Starry Knight Flamel', '圣夜骑士团·弗拉梅尔', 'ホーリーナイツ・フラムエル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：对方怪兽的攻击宣言时，把手卡·场上的这张卡送去墓地才能发动。从手卡把1只龙族·光属性·7星怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己的场上·墓地1只龙族·光属性·7星怪兽为对象才能发动。那只怪兽回到持有者手卡。这个效果在对方回合也能发动。'),
(44818, 'Starry Knight Orbitael', '圣夜骑士团·奥比泰尔', 'ホーリーナイツ・オルビタエル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 400, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只光属性怪兽为对象才能发动。那只怪兽解放，从卡组选1张「圣夜骑士」魔法·陷阱卡在自己场上盖放。这个效果在对方回合也能发动。 ②：这张卡在墓地存在，自己场上的表侧表示的龙族·光属性·7星怪兽回到手卡的场合才能发动。这张卡特殊召唤。'),
(23220533, 'Starry Knight Rayel', '圣夜骑士团·瑞尔', 'ホーリーナイツ・レイエル', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1张「圣夜骑士」魔法·陷阱卡加入手卡。 ②：把墓地的这张卡除外，以「圣夜骑士团·瑞尔」以外的自己墓地1只「圣夜骑士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(58406094, 'Starry Knight Sky', '辉煌的圣夜', '煌めく聖夜', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在场地区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「圣夜骑士」怪兽或者龙族·光属性·7星怪兽召唤。 ②：自己回合，自己场上的表侧表示的龙族·光属性·7星怪兽回到手卡的场合才能发动。自己从卡组抽1张。'),
(90835938, 'Starry Night, Starry Dragon', '圣夜的煌龙', '聖夜に煌めく竜', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2500, 2300, '①：这张卡从手卡的召唤·特殊召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：场上的这张卡不会被和暗属性怪兽的战斗破坏，不会被暗属性怪兽的效果破坏。 ③：1回合1次，这张卡向对方怪兽攻击的伤害步骤开始时才能发动。那只对方怪兽直到结束阶段除外。这个效果发动的场合，这张卡只再1次可以继续攻击。'),
(15306543, 'Stars Align Above the Shrine', '星逢之神篱', '星逢の神籬', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，可以发动。从自己场上的灵魂怪兽以及「灵魂鸟衍生物」之中让等级合计直到变成仪式召唤的怪兽的等级以上为止解放，从卡组把1只风属性仪式怪兽仪式召唤。 ②：1回合最多2次，自己场上的表侧表示的风属性怪兽回到自己手卡的场合，可以从以下效果选择1个发动。 ●自己的墓地·除外状态的1只灵魂怪兽或1张仪式魔法卡加入手卡。 ●从卡组把1张「星逢的天河」在自己场上盖放。'),
(20417688, 'Stars Align across the Milky Way', '星逢之天河', '星逢の天河', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只仪式怪兽给对方观看才能发动。和那只怪兽是卡名不同并是等级相同的1只仪式怪兽从卡组加入手卡。 ②：把墓地的这张卡除外，从手卡把1张仪式魔法卡送去墓地才能发动。这个效果变成和那张仪式魔法卡发动时的仪式召唤效果相同。'),
(37720300, 'Starship Adjust Plane', '星舰调节机', 'スターシップ・アジャスト・プレーン', 'Effect Monster', 'Machine', 'WIND', 3, 500, 1100, '这个卡名的效果1回合只能使用1次。 ①：以自己场上1只其他的机械族怪兽为对象才能发动。那只怪兽和这张卡的等级直到回合结束时变成那2只的等级合计的等级。这个效果的发动后，直到回合结束时自己不是机械族超量怪兽不能从额外卡组特殊召唤。'),
(15458892, 'Starship Spy Plane', '星舰侦察机', 'スターシップ・スパイ・プレーン', 'Effect Monster', 'Machine', 'WIND', 4, 1100, 500, '对方场上有超量怪兽存在的场合，这张卡可以从手卡特殊召唤。此外，这张卡从手卡的特殊召唤成功时，选择对方场上1张魔法·陷阱卡回到持有者手卡。'),
(74906081, 'Startling Stare of the Snake-Eyes', '睥睨统摄之蛇眼', '睨み統べるスネークアイズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的「蛇眼」怪兽的等级合计是2星以上的场合，可以从以下效果选择1个发动。 ●以对方的场上（表侧表示）·墓地1只怪兽为对象才能发动。那只怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ●以自己·对方场上1张当作永续魔法卡使用的怪兽卡为对象才能发动。那张卡在自己场上特殊召唤。'),
(93729065, 'Starving Venemy Dragon', '凶饿蛊龙', 'スターヴ・ヴェネミー・ドラゴン', 'Pendulum Effect Fusion Monster', 'Dragon', 'DARK', 7, 2500, 2000, '暗属性怪兽＋灵摆怪兽 这个卡名的①的怪兽效果1回合只能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。直到结束阶段，这张卡当作和那只怪兽同名卡使用，得到相同效果。那之后，作为对象的怪兽的攻击力·守备力下降500，效果无效化，给与对方500伤害。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(22070401, 'Starving Venemy Lethal Dose Dragon', '凶饿蛊死灭龙', 'スターヴ・ヴェネミー・リーサルドーズ・ドラゴン', 'Pendulum Effect Fusion Monster', 'Dragon', 'DARK', 8, 2800, 2000, '暗属性灵摆怪兽×3 ①：每次场上的卡被送去墓地，每有1张给这张卡放置1个蛊指示物。 ②：龙族·暗属性怪兽以外的场上的怪兽的攻击力下降场上的蛊指示物数量×200。 ③：1回合1次，自己主要阶段才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效。 ④：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(41209827, 'Starving Venom Fusion Dragon', '凶饿猛毒结合龙', 'スターヴ・ヴェノム・フュージョン・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 8, 2800, 2000, '衍生物以外的场上的暗属性怪兽×2 ①：这张卡融合召唤的场合才能发动。这张卡的攻击力直到回合结束时上升对方场上1只特殊召唤的怪兽的攻击力数值。 ②：1回合1次，以对方场上1只5星以上的怪兽为对象才能发动。这张卡直到结束阶段得到和那只怪兽的原本的卡名·效果相同的卡名·效果。 ③：融合召唤的这张卡被破坏的场合才能发动。对方场上的特殊召唤的怪兽全部破坏。'),
(39915560, 'Starving Venom Predapower Fusion Dragon', '凶饿猛毒捕食结合龙', 'スターヴ・ヴェノム・プレデター・フュージョン・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 10, 3600, 2500, '暗属性融合怪兽＋融合怪兽 这个卡名在规则上也当作「捕食植物」卡使用。这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，魔法·陷阱·怪兽的效果发动时才能发动。自己或者对方场上1只有捕食指示物放置的怪兽解放，那个发动无效。 ②：融合召唤的这张卡被对方送去墓地的场合，以自己墓地1只暗属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(5148778, 'Starving Venom Wing Dragon', NULL, NULL, 'Pendulum Effect Fusion Monster', 'Dragon', 'DARK', 10, 3300, 2500, NULL),
(23626223, 'Statue of Anguish Pattern', '苦纹样的土像', '苦紋様の土像', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（岩石族·地·7星·攻0/守2500）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ②：只要这张卡以外的当作怪兽使用的陷阱卡在怪兽区域存在，对方不能把这张卡的效果特殊召唤的这张卡作为效果的对象。 ③：这张卡的效果特殊召唤的这张卡存在的状态，自己的魔法与陷阱区域的卡在怪兽区域特殊召唤的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(65810489, 'Statue of the Wicked', '黄金邪神像', '黄金の邪神像', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '盖放的这张卡被破坏送去墓地时，在自己场上把1只「邪神衍生物」（恶魔族·暗·4星·攻/守1000）特殊召唤。'),
(92854392, 'Staunch Defender', '拦路的强敌', '立ちはだかる強敵', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方进行攻击宣言时这张卡才能发动。选择自己场上1张表侧表示的怪兽。这张卡发动回合，对方只能以所选择的这只怪兽为攻击对象，且必须用所有表侧攻击表示的怪兽攻击所选择的这只怪兽。'),
(49964567, 'Staysailor Romarin', '支索帆水手・萝玛琳', 'ステイセイラ・ロマリン', 'Tuner Monster', 'Plant', 'LIGHT', 4, 1600, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只表侧表示怪兽为对象才能发动。选那只怪兽以外的自己场上1只植物族怪兽送去墓地，作为对象的怪兽在这个回合只有1次不会被战斗·效果破坏。这个效果在对方回合也能发动。 ②：这张卡被效果送去墓地的场合才能发动。从卡组·额外卡组把1只5星以下的植物族怪兽送去墓地。'),
(64413994, 'Stealth Angecradle', '隐密天使-摇篮镰天使', 'ステルス・アンジュ－クレイドル', 'Normal Monster', 'Fairy', 'DARK', 8, 2700, 2700, '被称为“为异端灵魂带来救赎的天使”的充满谜团的存在。有“那个”经过后留下的只有永远的静寂——有天使经过。'),
(3510565, 'Stealth Bird', '隐形鸟', 'ステルスバード', 'Effect Monster', 'Winged Beast', 'DARK', 3, 700, 1700, '①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转召唤成功的场合发动。给与对方1000伤害。'),
(94942656, 'Stealth Kragen Spawn', '隐形蜇拉肯・碟状幼体', 'ステルス・クラーゲン・エフィラ', 'XYZ Monster', 'Aqua', 'WATER', 4, 1900, 1500, '水属性4星怪兽×2 ①：1回合1次，自己·对方的主要阶段才能发动。选对方场上1只水属性怪兽破坏。 ②：「No.」超量怪兽的效果特殊召唤的这张卡被破坏的场合才能发动。从自己墓地选最多有这张卡持有的超量素材数量的这张卡以外的「隐形水母怪」怪兽特殊召唤。并且可以再给那些特殊召唤的怪兽各从自己墓地选最多1只水属性怪兽作为那超量素材。'),
(98049038, 'Stealthroid', '隐形机人', 'ステルスロイド', 'Effect Monster', 'Machine', 'DARK', 4, 1200, NULL, '自己场上有这张卡以外的名字带有「机人」的怪兽存在的场合，这张卡进行战斗的自己回合的战斗阶段结束时，把场上1张魔法或者陷阱卡破坏。'),
(5368615, 'Steam Gyroid', '蒸汽旋翼机人', 'スチームジャイロイド', 'Fusion Monster', 'Machine', 'EARTH', 6, 2200, 1600, '「旋翼机人」＋「蒸汽机人」'),
(98588427, 'Steam Knight - BULLauncher', '包烤蒸骑-B公牛枪炮', '包焼蒸騎－BULLauncher', 'Normal Monster', 'Beast-Warrior', 'FIRE', 4, 1800, 200, '「B公牛枪炮(BULLauncher)」是在日渐改良「Coc-OS(可口食操作系统)」及「BFS(炖牛肉)装甲」的过程中受「马德拉酒」之命反复试错下最终开发的3架「铝箔纸包装机(Foil-Packer)」之内专为炮击&白天战斗而特化的支援机。凭借其换装成「牛肉光束步枪(Beef-Rifle)」等武装而令「包烤蒸骑」应对中·远距离作战一事成为可能。此外「B公牛枪炮(BULLauncher)」通过跟专为高速&空中战斗而特化的「W鸡翼装备(WINGear)」及专为接近&强袭战斗而特化的「B野猪武器(BOARms)」进行“熟成合体”，还会让热量很高的「包烤兽神-BW」降临。'),
(23923758, 'Steam Knight - Hamburk', '包烤蒸骑-汉堡排', '包焼蒸騎－ハンバルク', 'Normal Monster', 'Warrior', 'FIRE', 8, 2500, 200, '以在工厂内慢慢被炼成的浓钢铁「BFS(炖牛肉)装甲」及通过跟高解析力「Coc-OS(可口食操作系统)」联动能按照战况换装成各种武装的特殊机构「铝箔纸包装机(Foil-Packer)」为装备的骑士团一员。尽管「汉堡排」的武装是标准型，但带有高热量的战斗风格是本格派，在人们那里拥有非常高的人气。通过接受女神「马德拉酒」的加护，那份力量还会进一步得到扩充。'),
(83295594, 'Steam Synchron', '蒸汽同步士', 'スチーム・シンクロン', 'Tuner Monster', 'Machine', 'WATER', 3, 600, 800, '①：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为同调素材作同调召唤。'),
(9047461, 'Steam Token', '黑羽－隐蓑之斯汽姆', 'BF－隠れ蓑のスチーム', 'Token', 'Aqua', NULL, NULL, NULL, NULL, NULL),
(3743515, 'Steamed Sabersaurus', '怒发冲天 军刀角龙', '怒髪天衝セイバーザウルス', 'XYZ Monster', 'Dinosaur', 'FIRE', 4, 2000, 600, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。自己的手卡·场上（表侧表示）1只恐龙族怪兽破坏。那之后，可以把场上1只怪兽的表示形式变更。 ②：其他的自己的恐龙族怪兽进行战斗的伤害步骤开始时才能发动。这张卡破坏，那只恐龙族怪兽的攻击力直到战斗阶段结束时上升2000。'),
(44729197, 'Steamroid', '蒸汽机人', 'スチームロイド', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 1800, '①：这张卡向对方怪兽攻击的伤害步骤内，攻击力上升500。这张卡被对方怪兽攻击的伤害步骤内，攻击力下降500。'),
(2396042, 'Steel Cavalry of Dinon', '迪隆的钢铁骑兵', 'ディノンの鋼鉄騎兵', 'Pendulum Effect Monster', 'Dinosaur', 'EARTH', 4, 1600, 2600, '①：这张卡和灵摆怪兽进行战斗的伤害步骤开始时发动。这张卡的攻击力·守备力直到伤害步骤结束时变成一半。'),
(29172562, 'Steel Ogre Grotto #1', '钢铁巨神像', '鋼鉄の巨神像', 'Normal Monster', 'Machine', 'EARTH', 5, 1400, 1800, '据域是被机械帝国所祭奠着的钢铁的巨神像。'),
(90908427, 'Steel Ogre Grotto #2', '铁腕巨人', '鉄腕ゴーレム', 'Normal Monster', 'Machine', 'EARTH', 6, 1900, 2200, '由钢铁制成的机械人偶。以惊人的怪力著称。'),
(13599884, 'Steel Scorpion', '铁蝎', '鉄のサソリ', 'Effect Monster', 'Machine', 'EARTH', 1, 250, 300, '机械族以外的怪兽攻击这张卡的场合，那只怪兽（以对方的回合来数）第3个回合的回合结束时破坏。'),
(2370081, 'Steel Shell', '钢甲壳', 'はがねの甲羅', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '水属性怪兽才能装备。装备怪兽的攻击力上升400，守备力下降200。'),
(32986898, 'Steel Star Regulator', '肃星之钢机', '粛星の鋼機', 'Link Monster', 'Machine', 'LIGHT', NULL, 1000, NULL, '连接怪兽以外的怪兽3只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升作为这张卡的连接素材的怪兽的原本的等级·阶级的合计×100。 ②：以持有这张卡的攻击力以下的攻击力的除连接怪兽以外的对方场上1只怪兽为对象才能发动。那只怪兽破坏。这张卡用超量怪兽为素材作连接召唤的场合，再给与对方破坏的怪兽的原本攻击力一半数值的伤害。'),
(7166709, 'Steel-Stringed Sacrifice', '钢弦祭他手', NULL, 'Effect Monster', 'Warrior', 'LIGHT', 1, 800, 1000, '这张卡在手卡·墓地存在的场合：可以把手卡1只5星以上的怪兽给对方出示，从以下效果选择1个发动（「钢弦祭他手」的以下效果1回合各能选择1次），发动后，这个回合中自己没有把出示怪兽或者原本卡名和那只怪兽相同的怪兽召唤的场合，结束阶段让自己失去1000基本分。 ●这张卡从手卡特殊召唤。 ●这张卡从自己墓地加入手卡。 ●从自己墓地把这张卡除外，从自己墓地把1只5星以上的怪兽加入手卡。'),
(53116300, 'Steelswarm Caller', '侵入魔鬼的呼唤者', 'インヴェルズを呼ぶ者', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, NULL, '把这张卡解放对名字带有「侵入魔鬼」的怪兽的上级召唤成功时，可以从自己卡组把1只4星以下的名字带有「侵入魔鬼」的怪兽特殊召唤。'),
(84488827, 'Steelswarm Caucastag', '侵入魔鬼·巨角', 'インヴェルズ・ガザス', 'Effect Monster', 'Fiend', 'DARK', 8, 2800, NULL, '把2只名字带有「侵入魔鬼」的怪兽解放对这张卡的上级召唤成功时，从以下效果选择1个发动。 ●这张卡以外的场上存在的怪兽全部破坏。 ●场上存在的魔法·陷阱卡全部破坏。'),
(54338958, 'Steelswarm Cell', '侵入魔鬼的魔细胞', 'インヴェルズの魔細胞', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。这张卡不能为名字带有「侵入魔鬼」的怪兽的上级召唤以外而解放，也不能作为同调素材。'),
(26722601, 'Steelswarm Gatekeeper', '侵入魔鬼的门番', 'インヴェルズの門番', 'Effect Monster', 'Fiend', 'DARK', 4, 1500, 1900, '只要这张卡在场上表侧表示存在，名字带有「侵入魔鬼」的怪兽表侧表示上级召唤成功的回合，自己在通常召唤外加上只有1次可以把怪兽通常召唤。'),
(62729173, 'Steelswarm Genome', '侵入魔鬼万能态', 'インヴェルズ万能態', 'Effect Monster', 'Fiend', 'DARK', 2, 1000, NULL, '名字带有「侵入魔鬼」的怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(58494728, 'Steelswarm Girastag', '侵入魔鬼·长锹', 'インヴェルズ・ギラファ', 'Effect Monster', 'Fiend', 'DARK', 7, 2600, NULL, '这张卡可以把1只名字带有「侵入魔鬼」的怪兽解放表侧攻击表示上级召唤。把名字带有「侵入魔鬼」的怪兽解放对这张卡的上级召唤成功时，可以选择对方场上存在的1张卡送去墓地，自己回复1000基本分。'),
(94092230, 'Steelswarm Hercules', '侵入魔鬼·威角', 'インヴェルズ・グレズ', 'Effect Monster', 'Fiend', 'DARK', 10, 3200, NULL, '这张卡不能特殊召唤。这张卡通常召唤的场合，必须把自己场上存在的3只名字带有「侵入魔鬼」的怪兽解放作召唤。可以把基本分支付一半，这张卡以外的场上存在的卡全部破坏。这个效果1回合只能使用1次。'),
(62007535, 'Steelswarm Longhorn', '侵入魔鬼·牛角', 'インヴェルズ・ホーン', 'Effect Monster', 'Fiend', 'DARK', 9, 3000, NULL, '把名字带有「侵入魔鬼」的怪兽解放对这张卡的上级召唤成功的场合，得到以下效果。可以支付1000基本分，选择场上存在的1只怪兽破坏。这个效果1回合只能使用1次。'),
(85505315, 'Steelswarm Mantis', '侵入魔鬼·螳镰', 'インヴェルズ・マディス', 'Effect Monster', 'Fiend', 'DARK', 5, 2200, NULL, '把名字带有「侵入魔鬼」的怪兽解放对这张卡的上级召唤成功时，可以支付1000基本分，选择自己墓地存在的1只名字带有「侵入魔鬼」的怪兽特殊召唤。'),
(22009013, 'Steelswarm Moth', '侵入魔鬼·飞蛾', 'インヴェルズ・モース', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, NULL, '把名字带有「侵入魔鬼」的怪兽解放对这张卡的上级召唤成功时，可以支付1000基本分，选择对方场上存在的最多2张卡回到持有者手卡。'),
(61888819, 'Steelswarm Origin', '侵入魔鬼基源', 'インヴェルズ・オリジン', 'Link Monster', 'Fiend', 'LIGHT', NULL, 2000, NULL, '「入魔」怪兽2只 ①：只要这张卡在额外怪兽区域存在，双方要从额外卡组往主要怪兽区域把怪兽特殊召唤的场合，不在这张卡所连接区不能出现。 ②：只要这张卡所连接区有怪兽存在，这张卡不会成为效果的对象，不会被战斗·效果破坏。 ③：1回合1次，场上的怪兽被战斗·效果破坏时才能发动。把最多有那些破坏的怪兽数量的4星以下的「入魔」怪兽从卡组守备表示特殊召唤。'),
(37926346, 'Steelswarm Roach', '侵入魔鬼·蟑蠊', 'インヴェルズ・ローチ', 'XYZ Monster', 'Fiend', 'DARK', 4, 1900, NULL, '4星怪兽×2 可以把这张卡1个超量素材取除，5星以上的怪兽的特殊召唤无效并破坏。'),
(90727556, 'Steelswarm Scout', '侵入魔鬼的斥候', 'インヴェルズの斥候', 'Effect Monster', 'Fiend', 'DARK', 1, 200, NULL, '自己场上没有魔法·陷阱卡存在的场合，自己的主要阶段1的开始时才能发动。墓地存在的这张卡在自己场上特殊召唤。这个效果发动的回合，自己不能把怪兽特殊召唤。这张卡不能为名字带有「侵入魔鬼」的怪兽的上级召唤以外而解放，也不能作为同调素材。'),
(99214782, 'Steelswarm Sentinel', '侵入魔鬼的步哨', 'インヴェルズの歩哨', 'Effect Monster', 'Fiend', 'DARK', 3, 1100, NULL, '只要这张卡在场上表侧攻击表示存在，场上表侧表示存在的5星以上的特殊召唤的怪兽不能把效果发动。'),
(35618486, 'Steelswarm Sting', '侵入魔鬼的先锐', 'インヴェルズの先鋭', 'Effect Monster', 'Fiend', 'DARK', 4, 1850, NULL, '自己场上存在的这张卡被送去墓地时，选择场上表侧表示存在的1只仪式·融合·同调怪兽破坏。'),
(99733359, 'Stegocyber', '盾航战车 电子剑龙', '盾航戦車ステゴサイバー', 'Effect Monster', 'Dinosaur', 'DARK', 6, 1200, 2400, '「盾航战车 电子剑龙」的效果1回合只能使用1次。 ①：这张卡在墓地存在，对方怪兽攻击的场合，那次伤害计算时支付1000基本分才能发动。这张卡从墓地特殊召唤，那次战斗发生的对自己的战斗伤害变成0。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(3322931, 'Stellar Wind Wolfrayet', '星风狼 沃尔夫拉叶', '星風狼ウォルフライエ', 'Synchro Monster', 'Beast', 'WIND', 9, 2500, NULL, '调整＋调整以外的怪兽1只以上 ①：「星风狼 沃尔夫拉叶狼」在自己场上只能有1只表侧表示存在。 ②：只要攻击力未满4000的这张卡在怪兽区域存在，每次这张卡以外的怪兽的效果发动，这张卡的攻击力上升300。 ③：1回合1次，这张卡的攻击力是4000以上的场合才能发动。这张卡和对方场上的怪兽全部回到持有者卡组。这个效果在对方回合也能发动。'),
(81810441, 'Stellarknight Alpha', '辉星骑士的因子', '星輝士の因子', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的「星骑士」怪兽才能装备。 ①：装备怪兽的攻击力·守备力上升500。装备怪兽不受对方的卡的效果影响。 ②：自己场上有「星骑士」怪兽以外的怪兽表侧表示存在的场合这张卡破坏。'),
(9272381, 'Stellarknight Constellar Diamond', '辉星骑士 星圣 璨钻', '星輝士 セイクリッド・ダイヤ', 'XYZ Monster', 'Wyrm', 'LIGHT', 5, 2700, 2000, '光属性5星怪兽×3只以上 这张卡也能在自己主要阶段2在「星辉士 星圣冬钻龙」以外的自己场上的「星骑士」超量怪兽上面重叠来超量召唤。 ①：只要持有超量素材的这张卡在怪兽区域存在，双方不能从卡组把卡送去墓地，从墓地回到手卡的卡不回到手卡而除外。 ②：对方把暗属性怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(56638325, 'Stellarknight Delteros', '辉星骑士 德塔特洛斯', '星輝士 デルタテロス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 2100, '4星怪兽×3 ①：只要持有超量素材的这张卡在怪兽区域存在，在自己把怪兽召唤·特殊召唤的成功时对方不能把魔法·陷阱·怪兽的效果发动。 ②：1回合1次，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡破坏。 ③：这张卡从场上送去墓地的场合才能发动。从手卡·卡组把1只「星骑士」怪兽特殊召唤。'),
(42589641, 'Stellarknight Triverr', '辉星骑士 特莱维尔', '星輝士 トライヴェール', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2100, 2500, '4星「星骑士」怪兽×3 把这张卡超量召唤的回合，自己不是「星骑士」怪兽不能特殊召唤。 ①：这张卡超量召唤的场合发动。场上的其他卡全部回到手卡。 ②：1回合1次，把这张卡1个超量素材取除才能发动。对方手卡随机1张送去墓地。 ③：持有超量素材的这张卡被送去墓地的场合，以自己墓地1只「星骑士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(22617205, 'Stellarknight Zefraxciton', '觉辉星骑士－源质西卜', '覚星輝士－セフィラビュート', 'Pendulum Effect Monster', 'Fiend', 'LIGHT', 4, 1900, NULL, '「觉星辉士-神数蝇王」的怪兽效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·灵摆召唤成功的场合，以这张卡以外的自己的怪兽区域·灵摆区域1张「星骑士」卡或者「神数」卡和对方场上盖放的1张卡为对象才能发动。那些卡破坏。'),
(41510920, 'Stellarnova Alpha', '神星之因子', '神星なる因子', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：怪兽的效果·魔法·陷阱卡发动时，把自己场上1只表侧表示的「星骑士」怪兽送去墓地才能发动。那个发动无效并破坏。那之后，自己从卡组抽1张。'),
(69678646, 'Stellarnova Bonds', '神星之系束', '神星なる繋束', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这个回合，自己不是超量怪兽不能从额外卡组特殊召唤。 ●选自己1张手卡丢弃，相同种族的怪兽不在自己场上存在的1只「星骑士」、「星圣」怪兽从卡组特殊召唤。 ●以最多有自己场上的「星骑士」、「星圣」怪兽数量的对方场上的表侧表示怪兽为对象才能发动。那些怪兽的效果直到回合结束时无效。'),
(5026221, 'Stellarnova Wave', '神星之波动', '神星なる波動', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，自己主要阶段以及对方战斗阶段才能把这个效果发动。从手卡把1只「星骑士」怪兽特殊召唤。'),
(83225447, 'Stim-Pack', '兴奋剂', 'ドーピング', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力上升700。自己的每次的准备阶段装备怪兽的攻击力下降200。'),
(57649113, 'Stinger the Electric Expeller', '退电针刺', '退電のスティンガー', 'Normal Tuner Monster', 'Psychic', 'WIND', 3, 800, 1000, '通过勇猛奋斗不断将迫近的外敌击退，属于沙丘防卫队的队士。那剑本应只为其应该守护的对象而挥舞。'),
(68167124, 'Stinging Swordsman', '针剑士', '針剣士', 'Effect Monster', 'Warrior', 'WIND', 1, 300, 600, '这张卡给与对方基本分战斗伤害时，对方的魔法与陷阱卡区域表侧表示存在的卡全部回到持有者手卡。'),
(37364101, 'Stoic Challenge', '克己挑战', 'ストイック・チャレンジ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '持有超量素材的超量怪兽才能装备。装备怪兽的攻击力上升自己场上的超量素材数量×600的数值，和对方怪兽的战斗给与对方基本分的战斗伤害变成2倍。此外，装备怪兽不能把效果发动。这张卡在对方的结束阶段时送去墓地。这张卡从场上离开时，装备怪兽破坏。「克己挑战」在自己场上只能有1张表侧表示存在。'),
(54359696, 'Stoic of Prophecy', '魔导术士 拉潘迪', '魔導術士 ラパンデ', 'Effect Monster', 'Spellcaster', 'WATER', 1, 300, 200, '这张卡被送去墓地时，从卡组把1只3星的名字带有「魔导」的怪兽加入手卡。'),
(63432835, 'Stone Armadiller', '岩石犰狳', 'ストーン・アルマジラー', 'Normal Monster', 'Rock', 'EARTH', 3, 800, 1200, '身体被像石头般坚固的毛覆盖着、守备坚固。'),
(68171737, 'Stone Dragon', '岩石龙', 'ストーン・ドラゴン', 'Normal Monster', 'Rock', 'EARTH', 7, 2000, 2300, '完全由岩石组成的龙。岩石的攻击很强。'),
(72269672, 'Stone Ghost', '岩石幽灵', 'ストーン・ゴースト', 'Normal Monster', 'Rock', 'EARTH', 4, 1200, 1000, '激怒它的话，头上的火山可是会爆发的哦。'),
(15023985, 'Stone Ogre Grotto', '岩石巨人', 'ストーンジャイアント', 'Normal Monster', 'Rock', 'EARTH', 5, 1600, 1500, '能将巨大的岩石堆积起来的岩石巨人。'),
(31812496, 'Stone Statue of the Aztecs', '阿兹特克石像', 'アステカの石像', 'Effect Monster', 'Rock', 'EARTH', 4, 300, 2000, '①：这张卡被攻击的场合，那次战斗发生的对对方的战斗伤害变成2倍。'),
(70786111, 'Stonehenge', '巨石阵', 'ストーンヘンジ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只攻击力0的怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。'),
(86555018, 'Stonehenge Methods', '环状列石术', 'ストーンヘンジ・メソッド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的名字带有「先史遗产」的怪兽被战斗或者卡的效果破坏送去墓地时才能发动。从卡组把1只4星以下的名字带有「先史遗产」的怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽不能把表示形式变更。'),
(63102017, 'Stop Defense', '『守备』封禁', '『守備』封じ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只守备表示怪兽为对象才能发动。那只对方怪兽变成表侧攻击表示。'),
(24232799, 'Storagepod', '脚纳母舰 超大腕龙', '脚納母艦ブラキオーバー', 'Fusion Monster', 'Machine', 'DARK', 6, 2500, 2500, '「机动要犀 铁犀三角龙」或「盾航战车 电子剑龙」＋机械族·恐龙族怪兽 这个卡名的②的效果1回合只能使用1次。 ①：只要从墓地特殊召唤的怪兽存在，这张卡不会被战斗破坏。 ②：这张卡在怪兽区域存在的状态，从手卡有怪兽特殊召唤的场合，以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。'),
(13210191, 'Storm', '风暴', '嵐', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的魔法·陷阱卡全部破坏。那之后，把破坏的卡数量的对方场上的魔法·陷阱卡破坏。'),
(15935204, 'Storm Caller', '风暴召唤师', 'ストーム・サモナー', 'Effect Monster', 'Psychic', 'WIND', 6, 2300, 2000, '只要这张卡在自己场上表侧表示存在，可以让这张卡以外的念动力族怪兽战斗破坏的对方怪兽不送去墓地，在对方卡组最上面放置。这张卡被卡的效果破坏时，这张卡的控制者受到这张卡的攻击力数值的伤害。'),
(89571015, 'Storm Cipher', '风暴密码人', 'ストームサイファー', 'Effect Monster', 'Cyberse', 'DARK', 4, 2400, NULL, '①：这张卡不能直接攻击，不能向额外怪兽区域的怪兽攻击。 ②：这张卡不受额外怪兽区域的怪兽发动的效果影响，不会被和额外怪兽区域的怪兽的战斗破坏。'),
(83195035, 'Storm Dragon''s Return', '龙岚归还', '竜嵐還帰', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以除外的1只自己或者对方的怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者手卡。'),
(39188539, 'Storm Shooter', '风暴射手', 'ストーム・シューター', 'Effect Monster', 'Winged Beast', 'WIND', 7, 2300, 500, '1回合只有1次，可以从下面的效果选择1个发动。 ●移动到没有使用的相邻的怪兽卡区域。 ●这张卡的正对面存在的1张对方的怪兽·魔法·陷阱卡回到持有者手卡。'),
(101303089, 'Storm-Bane Dragon Destorbim', NULL, NULL, 'Synchro Monster', 'Dragon', 'DARK', 11, 3000, 2800, NULL),
(5650082, 'Storming Mirror Force', '神风防护罩 －大气之力－', '神風のバリア －エア・フォース－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。对方场上的攻击表示怪兽全部回到持有者手卡。'),
(29013526, 'Storming Wynn', '猛吹之薇茵', '吹き荒れるウィン', 'Effect Monster', 'Spellcaster', 'WIND', 4, 800, 1500, '可以把自己场上除这张卡以外的1只风属性怪兽做祭品，从手卡特殊召唤1只风属性怪兽。这个效果1回合只能使用1次。这个效果特殊召唤的怪兽，在「猛吹之薇茵」从自己场上离开的场合破坏。'),
(25173686, 'Straight Flush', '同花顺', 'ストレートフラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方场上的魔法与陷阱卡区域全部有卡存在的场合才能发动。对方的魔法与陷阱卡区域存在的卡全部破坏。'),
(300101002, 'Straight to the Grave', NULL, NULL, 'Skill Card', 'Bonz', NULL, NULL, NULL, NULL, NULL),
(50032342, 'Strategist of the Ice Barrier', '冰结界的军师', '氷結界の軍師', 'Effect Monster', 'Spellcaster', 'WATER', 4, 1600, 1600, '①：1回合1次，从手卡把1只「冰结界」怪兽送去墓地才能发动。自己抽1张。'),
(86209650, 'Stray Asmodian', '迷走恶魔', '迷走悪魔', 'Effect Monster', 'Fiend', 'FIRE', 3, 1300, 1700, '这张卡被战斗破坏送去墓地时，双方回复800基本分。'),
(60764581, 'Stray Lambs', '迷途的羔羊', '迷える仔羊', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·反转召唤·特殊召唤。 ①：在自己场上把2只「羔羊衍生物」（兽族·地·1星·攻/守0）守备表示特殊召唤。'),
(20212491, 'Stray Purrely Street', '皮尔莉流浪之街', 'ストレイ・ピュアリィ・ストリート', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的「纯爱妖精」怪兽在特殊召唤的回合不会成为对方的效果的对象。 ②：1回合1次，自己场上的表侧表示的「纯爱妖精」超量怪兽因对方从场上离开的场合发动。从自己的卡组·墓地选1只1星「纯爱妖精」怪兽特殊召唤。 ③：双方的结束阶段，以场上1只「纯爱妖精」超量怪兽为对象才能发动。从自己的卡组·墓地选1张「纯爱妖精」速攻魔法卡在那只怪兽下面重叠作为超量素材。'),
(27415516, 'Stream, Dragon Ruler of Droplets', '水征龙－川流', '水征竜－ストリーム', 'Effect Monster', 'Dragon', 'WATER', 4, 1600, 2000, '这个卡名的效果1回合只能使用1次。 ①：把1只龙族或水属性的怪兽和这张卡从手卡丢弃才能发动。从卡组把1只「瀑征龙-潮龙」特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(96239878, 'Strength in Unity', '集结之力', '束ねられし力', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己作使用「青眼白龙」或者「黑魔术师」的仪式·融合召唤成功的场合，以对方的场上·墓地1张卡为对象才能发动。那张卡除外。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己墓地1只7星以上的通常怪兽为对象才能发动。那只怪兽加入手卡或回到卡组。'),
(13002461, 'Strength of Prophecy', '魔导战士 法尔丝', '魔導戦士 フォルス', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1500, 1400, '1回合1次，让自己墓地1张名字带有「魔导书」的魔法卡回到卡组，选择场上1只魔法师族怪兽才能发动。选择的怪兽的等级上升1星，攻击力上升500。'),
(41006930, 'Strike Ninja', '速攻的黑衣忍者', '速攻の黒い忍者', 'Effect Monster', 'Warrior', 'DARK', 4, 1700, 1200, '这个卡名的效果1回合只能使用1次。 ①：从自己墓地把2只暗属性怪兽除外才能发动。表侧表示的这张卡直到结束阶段除外。这个效果在对方回合也能发动。'),
(5795980, 'Strike of the Monarchs', '帝王的轰毅', '帝王の轟毅', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把自己场上1只5星以上的通常召唤的表侧表示怪兽解放，以场上1张表侧表示的卡为对象才能发动。那张卡的效果直到回合结束时无效。那之后，自己从卡组抽1张。 ②：自己主要阶段把墓地的这张卡除外，宣言1个属性才能发动。场上的全部表侧表示怪兽直到回合结束时变成宣言的属性。'),
(30643162, 'Strike Slash', '强袭冲击', 'ストライク・ショット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上存在的怪兽攻击宣言时才能发动。那只怪兽的攻击力直到结束阶段时上升700。那只怪兽攻击守备表示怪兽的场合，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(73539069, 'Striker Dragon', '击针龙', 'ストライカー・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1000, NULL, '4星以下的龙族怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「旋转引导扇区」加入手卡。 ②：以自己场上1只表侧表示怪兽和自己墓地1只「弹丸」怪兽为对象才能发动。作为对象的场上的怪兽破坏，作为对象的墓地的怪兽加入手卡。'),
(74715061, 'Striping Partner', '条带化伙伴犬', 'ストライピング・パートナー', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1200, 1600, '这张卡不能通常召唤，用这张卡的①的效果才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：自己场上发动的怪兽的效果的发动无效的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功时，以自己墓地1只4星以下的电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(23770284, 'Strong Wind Dragon', '强风龙', 'ストロング・ウィンド・ドラゴン', 'Effect Monster', 'Dragon', 'WIND', 6, 2400, 1000, '①：把1只龙族怪兽解放对这张卡的上级召唤成功的场合发动。这张卡的攻击力上升解放的那只怪兽的原本攻击力一半数值。 ②：这张卡不会被和相同攻击力的怪兽的战斗破坏。 ③：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(23535429, 'Stronghold Guardian', '牙城守护者', '牙城のガーディアン', 'Effect Monster', 'Warrior', 'EARTH', 4, NULL, 1500, '自己场上守备表示存在的怪兽被攻击的场合，那次伤害步骤时可以把这张卡从手卡送去墓地，进行那次战斗的自己怪兽的守备力直到结束阶段时上升1500。'),
(27157727, 'Stronghold the Hidden Fortress', '隐匿城 坚实堡垒', '隠し砦 ストロング・ホールド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成持有以下效果的效果怪兽（机械族·地·4星·攻0/守2000）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ●这张卡的攻击力上升自己场上的「光之黄金柜」以及有那个卡名记述的怪兽数量×1000。 ●1回合1次，自己场上有「光之黄金柜」存在的场合，对方怪兽的攻击宣言时才能发动。那只怪兽破坏。'),
(13955608, 'Stronghold the Moving Fortress', '机动城 堡垒', '機動砦 ストロング・ホールド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（机械族·地·4星·攻0/守2000）在怪兽区域守备表示特殊召唤。这张卡也当作陷阱卡使用。 ②：自己场上有「绿色零件」「红色零件」「黄色零件」存在的场合，这张卡的效果特殊召唤的这张卡的攻击力上升3000。'),
(71068263, 'Stuffed Animal', '食人玩偶', 'くいぐるみ', 'Normal Monster', 'Warrior', 'EARTH', 3, 1200, 900, '看起来是个可爱的布娃娃，用拉链的嘴巴蒙上敌人并加以攻击。'),
(34646691, 'Stumbling', '绊倒', 'つまずき', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '召唤·反转召唤·特殊召唤成功的怪兽成为守备表示。'),
(81489939, 'Stygian Dirge', '魔人之歌', 'デビリアン・ソング', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，对方场上表侧表示存在的全部怪兽的等级下降1星。'),
(50732780, 'Stygian Security', '地狱治安警察', 'ヘル・セキュリティ', 'Tuner Monster', 'Fiend', 'DARK', 1, 100, 600, '①：这张卡被战斗破坏送去墓地的场合发动。从卡组把1只恶魔族·1星怪兽特殊召唤。'),
(86137485, 'Stygian Sergeants', '地狱双警', 'ヘル・ツイン・コップ', 'Synchro Monster', 'Fiend', 'DARK', 5, 2200, 1800, '恶魔族调整＋调整以外的怪兽1只以上 ①：这张卡战斗破坏对方怪兽送去墓地时才能发动。这张卡直到战斗阶段结束时攻击力上升800，只再1次可以继续攻击。'),
(13521194, 'Stygian Street Patrol', '地狱公路巡警', 'ヘルウェイ・パトロール', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 1200, '①：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本等级×100伤害。 ②：把墓地的这张卡除外才能发动。从手卡把1只攻击力2000以下的恶魔族怪兽特殊召唤。'),
(30106950, 'Suanni, Fire of the Yang Zing', '炎龙星－狻猊', '炎竜星－シュンゲイ', 'Effect Monster', 'Wyrm', 'FIRE', 4, 1900, NULL, '「炎龙星-狻猊」的①的效果1回合只能使用1次。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「炎龙星-狻猊」以外的1只「龙星」怪兽守备表示特殊召唤。 ②：1回合1次，对方的主要阶段以及战斗阶段才能发动。只用自己场上的「龙星」怪兽为同调素材作同调召唤。 ③：这张卡为同调素材的同调怪兽攻击力·守备力上升500。'),
(54485355, 'Sublimation Knight', '升华骑士－蒸汽圣战士', '昇華騎士－エクスパラディン', 'Effect Monster', 'Warrior', 'FIRE', 3, 1300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡·卡组选1只战士族·炎属性怪兽或者二重怪兽当作攻击力上升500的装备卡使用给这张卡装备。 ②：有二重怪兽装备的这张卡被对方破坏的场合才能发动。那些装备的二重怪兽从墓地尽可能往自己场上特殊召唤。这个效果特殊召唤的怪兽当作再1次召唤的状态使用。'),
(87116749, 'Submareed Tour Ride', '游览艇 潜艇利兹鱼', '游覧艇サブマリード', 'Effect Monster', 'Dinosaur', 'WATER', 6, 2200, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有通常怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：1回合只有1次，自己的通常怪兽不会被和效果怪兽的战斗破坏。'),
(63948258, 'Submarine Frog', '未知青蛙', '未知ガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 1200, 600, '这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(99861526, 'Submarineroid', '潜艇机人', 'サブマリンロイド', 'Effect Monster', 'Machine', 'WATER', 4, 800, 1800, '这张卡可以直接攻击对方玩家。这个时候，给与对方玩家的战斗伤害变成这张卡的原本攻击力的数值。此外，伤害步骤结束时这张卡的表示形式可以变成守备表示。'),
(5014629, 'Submersible Carrier Aero Shark', '潜航母舰 航空鲨', '潜航母艦エアロ・シャーク', 'XYZ Monster', 'Fish', 'WATER', 3, 1900, 1000, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。给与对方为自己的除外状态的怪兽数量×100伤害。'),
(89693655, 'Subspace Battle', '亚空间战斗', '亜空間バトル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以下效果3次适用。 ●双方各自从自身卡组选1只攻击力?以外的怪兽，给双方确认。攻击力较高方的怪兽加入选那只的玩家手卡。攻击力较低方的怪兽破坏，选那只的玩家受到500伤害。攻击力相同的场合，选的怪兽回到卡组。这个回合，双方不能把这个效果让自身选的怪兽以及那些同名怪兽的怪兽效果发动。'),
(20663556, 'Substitoad', '交换蛙', 'イレカエル', 'Effect Monster', 'Aqua', 'WATER', 1, 100, 2000, '把自己场上存在的1只怪兽作为祭品。从自己卡组选择1只名字带有「青蛙」的怪兽在自己场上特殊召唤。只要这张卡在场上存在，名字带有「青蛙」的怪兽不会被战斗破坏。'),
(43994202, 'Subsurface Stage Divers', '迅疾三分利', '素早きは三文の徳', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的怪兽只有衍生物以外的同名怪兽3只的场合才能发动。从卡组把3只同名怪兽加入手卡。这张卡的发动后，直到回合结束时自己不能把这个效果加入手卡的怪兽以及那些同名怪兽通常召唤·特殊召唤，那些怪兽效果不能发动。'),
(28369508, 'Subterror Behemoth Burrowing', '地中骇界邪龙的潜伏', 'サブテラーマリスの潜伏', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己墓地把1只「地中族」怪兽除外才能发动。直到回合结束时，自己场上的里侧表示怪兽不会被效果破坏，不会成为对方的效果的对象。 ②：场上的这张卡被效果破坏的场合才能发动。从卡组把1只「地中族」怪兽加入手卡。 ③：把墓地的这张卡除外，以自己场上1只「地中族」怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(95218695, 'Subterror Behemoth Dragossuary', '地中骇界邪龙 亡骸阿尔沃兰', 'サブテラーマリス・アルラボーン', 'Flip Effect Monster', 'Zombie', 'EARTH', 6, 2400, 1600, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合才能发动。这个回合，自己场上的「地中族」卡不会被对方的效果破坏。'),
(74937659, 'Subterror Behemoth Fiendess', '地中骇界邪龙之妖魔', 'サブテラーマリスの妖魔', 'Link Monster', 'Wyrm', 'EARTH', NULL, 2000, NULL, '反转怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升作为这张卡的连接素材的「地中族」怪兽的原本等级合计×100。 ②：自己主要阶段才能发动。从卡组把1只反转怪兽送去墓地，从手卡把1只怪兽在这张卡所连接区里侧守备表示特殊召唤。 ③：1回合1次，这张卡所连接区的怪兽反转的场合发动。从自己的卡组·墓地把1只反转怪兽加入手卡。'),
(1151281, 'Subterror Behemoth Phospheroglacier', '地中骇界邪龙 冰川爱奥尼亚', 'サブテラーマリス・グライオース', 'Flip Effect Monster', 'Aqua', 'EARTH', 8, 2600, 2500, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合才能发动。从卡组选1张卡送去墓地。'),
(47556396, 'Subterror Behemoth Speleogeist', '地中骇界邪龙 冥魂埃勾斯特', 'サブテラーマリス・エルガウスト', 'Flip Effect Monster', 'Fiend', 'EARTH', 11, 3000, 1400, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合，以场上1只怪兽为对象才能发动。那只怪兽是守备表示的场合，变成表侧攻击表示。那只怪兽的攻击力变成0。'),
(78202553, 'Subterror Behemoth Stalagmo', '地中骇界邪龙 煤岩直布罗陀', 'サブテラーマリス・ジブラタール', 'Flip Effect Monster', 'Rock', 'EARTH', 10, 2800, 2100, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合才能发动。从手卡丢弃1只「地中族」怪兽，自己从卡组抽2张。'),
(65976795, 'Subterror Behemoth Stygokraken', '地中骇界邪龙 潜渊亚得里亚', 'サブテラーマリス・アクエドリア', 'Flip Effect Monster', 'Sea Serpent', 'EARTH', 5, 1400, 2600, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合，以自己场上的「地中族邪界」怪兽数量的场上盖放的卡为对象才能发动。那些卡破坏。'),
(92970404, 'Subterror Behemoth Ultramafus', '地中骇界邪龙 熔烬巴利阿里', 'サブテラーマリス・バレスアッシュ', 'Flip Effect Monster', 'Pyro', 'EARTH', 12, 3000, 1800, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合才能发动。这张卡以外的场上的表侧表示怪兽全部变成里侧守备表示。'),
(42713844, 'Subterror Behemoth Umastryx', '地中骇界邪龙 地蜥利古里亚', 'サブテラーマリス・リグリアード', 'Flip Effect Monster', 'Reptile', 'EARTH', 7, 2000, 2700, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合，以对方场上1只怪兽为对象才能发动。那只怪兽除外。'),
(21607304, 'Subterror Behemoth Voltelluric', '地中骇界邪龙 飞雷第勒尼安', 'サブテラーマリス・ボルティニア', 'Flip Effect Monster', 'Thunder', 'EARTH', 9, 1900, 3000, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的表侧表示怪兽变成里侧表示时，自己场上没有表侧表示怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ③：这张卡反转的场合，以对方场上1只里侧表示怪兽为对象才能发动。那只怪兽的控制权直到下次的自己结束阶段得到。'),
(68001309, 'Subterror Cave Clash', '地中骇界的激斗', 'サブテラーの激闘', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的「地中族」怪兽的攻击力·守备力上升场上的里侧表示怪兽数量×500。 ②：1回合1次，自己的「地中族」怪兽给与对方战斗伤害时，以「地中族的激斗」以外的自己墓地1张「地中族」卡为对象才能发动。那张卡加入手卡。'),
(74762582, 'Subterror Fiendess', '地中骇界的妖魔', 'サブテラーの妖魔', 'Effect Monster', 'Spellcaster', 'EARTH', 1, 800, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把魔法·陷阱·怪兽的效果发动时，把手卡·场上的这张卡送去墓地，以自己场上1只「地中族」怪兽为对象才能发动。那个发动无效。那之后，作为对象的怪兽变成里侧守备表示。 ②：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示，选自己的手卡·墓地1只「地中族」怪兽表侧守备表示或者里侧守备表示特殊召唤。'),
(74640994, 'Subterror Final Battle', '地中骇界的决战', 'サブテラーの決戦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。发动后这张卡不送去墓地，直接盖放。 ●选自己场上1只里侧表示的「地中族」怪兽变成表侧攻击表示或者表侧守备表示。 ●选场上1只表侧表示的「地中族」怪兽变成里侧守备表示。 ●选场上1只表侧表示的「地中族」怪兽，那只怪兽的攻击力·守备力直到回合结束时变成那个原本的攻击力和守备力合计数值。 ●这个回合，「地中族」卡的所发动的效果不会被无效化。'),
(16428514, 'Subterror Guru', '地中骇界的导师', 'サブテラーの導師', 'Flip Effect Monster', 'Dragon', 'EARTH', 4, 1600, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合才能发动。从卡组把「地中族导师」以外的1张「地中族」卡加入手卡。 ②：以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽和这张卡变成里侧守备表示。自己场上有这张卡以外的「地中族」卡存在的场合，这个效果在对方回合也能发动。'),
(39581190, 'Subterror Nemesis Archer', '地中骇界的射手', 'サブテラーの射手', 'Effect Monster', 'Fairy', 'EARTH', 3, 1600, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有这张卡以外的「地中族」怪兽存在，这张卡向对方的里侧守备表示怪兽攻击的伤害步骤开始时才能发动。那只对方怪兽回到持有者卡组。 ②：场上的这张卡被战斗·效果破坏送去墓地的场合才能发动。从卡组把1只「地中族」怪兽表侧守备表示或者里侧守备表示特殊召唤。'),
(68823957, 'Subterror Nemesis Defender', '地中骇界的刀匠', 'サブテラーの刀匠', 'Effect Monster', 'Beast-Warrior', 'EARTH', 2, 100, 2000, '①：只让自己场上的里侧表示怪兽1只成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时，把手卡·场上的这张卡送去墓地，以那只里侧表示怪兽以外的自己场上1只怪兽为对象才能发动。那个对象转移为作为正确对象的那只怪兽。 ②：只要自己场上有里侧表示怪兽存在，这张卡不会被战斗·效果破坏。'),
(16719140, 'Subterror Nemesis Warrior', '地中骇界的战士', 'サブテラーの戦士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「地中族」怪兽送去墓地才能发动。原本等级合计直到变成那只「地中族」怪兽的等级以上为止，把这张卡和自己场上的怪兽1只以上解放，把那只「地中族」怪兽表侧守备表示或者里侧守备表示从墓地特殊召唤。这个效果在对方回合也能发动。 ②：自己场上的「地中族邪界」怪兽反转的场合才能发动（伤害步骤也能发动）。墓地的这张卡特殊召唤。'),
(73575650, 'Subterror Succession', '地中骇界的继承', 'サブテラーの継承', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。发动后这张卡不送去墓地，直接盖放。 ●从手卡以及自己场上的表侧表示怪兽之中选1只怪兽送去墓地，相同属性而卡名不同的1只反转怪兽从卡组加入手卡。 ●从手卡以及自己场上的表侧表示怪兽之中选1只反转怪兽送去墓地，相同属性而原本等级低的1只怪兽从卡组加入手卡。'),
(6859683, 'Success Probability 0%', '成功确率0%', '成功確率０％', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从对方额外卡组随机选择2张融合怪兽送去墓地。'),
(69145169, 'Successor Soul', '承继之魂', '受け継ぎし魂', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己只能用1只怪兽攻击。 ①：把自己场上1只效果怪兽解放，以对方场上1只效果怪兽为对象才能发动。那只怪兽送去墓地。那之后，从手卡·卡组把1只7星以上的通常怪兽在自己场上特殊召唤。'),
(55291359, 'Succubus Knight', '女夜魔骑士', 'サキュバス・ナイト', 'Normal Monster', 'Warrior', 'DARK', 5, 1650, 1300, '咏唱起魔法，给予对方血的祭礼的恶魔魔法战士。'),
(81756619, 'Succumbing-Song Morganite', '讴歌死亡的绿柱魔瞳', '死を謳う魔瞳', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这次决斗中，以下效果各适用。 ●自己不能把手卡的怪兽的效果发动。 ●自己怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。 ●自己怪兽用和对方怪兽的战斗给与对方的战斗伤害变成2倍。 ②：把墓地的这张卡除外才能发动。从卡组把1张「魔瞳」卡加入手卡。那之后，选自己1张手卡回到卡组最下面。'),
(23611122, 'Sudden Thunder Swamp', '急雷之泥沼', '急雷の泥沼', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，以下效果可以适用。 ●选自己1张手卡丢弃，除丢弃的卡外的1张持有把自身作为怪兽特殊召唤效果的永续陷阱卡从自己的卡组·墓地到自己场上盖放。 ②：自己场上的卡因战斗·效果而破坏，被送去墓地的场合或者被表侧除外的场合，以那之内的1张为对象才能发动。那1张同名卡从卡组加入手卡。'),
(98434877, 'Suijin', '水魔神－苏迦', '水魔神－スーガ', 'Effect Monster', 'Aqua', 'WATER', 7, 2500, 2400, '①：只在这张卡在场上表侧表示存在才有1次，这张卡被攻击的伤害计算时，以1只攻击怪兽为对象才能发动。那只攻击怪兽的攻击力变成0。'),
(77751766, 'Summer Schoolwork Successful!', '火器的祝台', '火器の祝台', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动的场合，给这张卡放置5个祝台指示物来发动。 ①：因魔法·陷阱卡的效果，从额外卡组有怪兽特殊召唤的场合或者从卡组有卡被送去墓地的场合发动。这张卡1个祝台指示物取除。那之后，这张卡的祝台指示物数量是0的场合，这张卡破坏，自己回复4000基本分。那之后，从自己的卡组·墓地把1张「祝台」陷阱卡在自己场上盖放。那之后，自己卡组的数量是1张以下的场合，自己决斗胜利。'),
(18114794, 'Summon Breaker', '召唤断路器', 'サモンブレーカー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，回合玩家作那个回合第3次的召唤·反转召唤·特殊召唤成功时，变成那个回合的结束阶段。这个效果在主要阶段1才发动。'),
(55375684, 'Summon Cloud', '召唤云', '召喚雲', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上没有怪兽存在的场合，可以从自己的手卡或者墓地把1只4星以下的名字带有「云魔物」的怪兽特殊召唤。这个效果1回合只有1次在自己的主要阶段才能使用。从墓地特殊召唤的场合这张卡破坏。'),
(41139112, 'Summon Dice', '召唤骰子', 'サモン・ダイス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：支付1000基本分才能发动。掷1次骰子，出现的数目的效果适用。 ●1·2：可以把1只怪兽召唤。 ●3·4：可以从自己墓地选1只怪兽特殊召唤。 ●5·6：可以从手卡把1只5星以上的怪兽特殊召唤。'),
(29724053, 'Summon Gate', '召唤之门', 'サモン・ゲート', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方各自在1回合只能有合计最多3只怪兽从额外卡组特殊召唤。'),
(23516703, 'Summon Limit', '召唤限制器', 'サモンリミッター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这个回合中对怪兽的召唤·反转召唤·特殊召唤已有合计2次以上成功的玩家只要这张卡在魔法与陷阱区域存在，不能把怪兽召唤·反转召唤·特殊召唤。'),
(48015771, 'Summon Over', '召唤过度', 'サモンオーバー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次怪兽特殊召唤给这张卡放置1个召唤指示物（最多6个）。 ②：有6个召唤指示物放置的这张卡不会被效果破坏。 ③：这张卡有6个召唤指示物放置的场合，双方玩家在自己主要阶段1开始时才能发动。这张卡送去墓地，对方场上的特殊召唤的怪兽全部送去墓地。'),
(89493368, 'Summon Reactor SK', '召唤反应机·大式', 'サモン・リアクター・AI', 'Effect Monster', 'Machine', 'DARK', 5, 2000, 1400, '只要这张卡在自己场上存在，对方场上有怪兽召唤、反转召唤、特殊召唤时，给与对方基本分800分伤害。这个效果1回合只能使用1次。这个效果使用的回合的战斗阶段时，可以把1只对方怪兽的攻击无效。可以把自己场上表侧表示存在的这张卡和「陷阱反应机·空式」「魔法反应机·袭式」各1只送去墓地，从自己的手卡·卡组·墓地把1只「巨人轰炸机·大空袭式」特殊召唤。'),
(42719764, 'Summon Shock', NULL, NULL, 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(61665245, 'Summon Sorceress', '召唤女巫', 'サモン・ソーサレス', 'Link Monster', 'Spellcaster', 'DARK', NULL, 2400, NULL, '衍生物以外的相同种族的怪兽2只以上 这个卡名的效果1回合只能使用1次。 ①：这张卡连接召唤的场合才能发动。从手卡把1只怪兽效果无效在作为这张卡所连接区的对方场上守备表示特殊召唤。那之后，可以把和这个效果特殊召唤的怪兽相同种族的1只怪兽从卡组效果无效守备表示特殊召唤。这个效果从卡组特殊召唤过的回合，自己不是原本种族和从卡组特殊召唤的那只怪兽相同的怪兽不能特殊召唤。'),
(71459861, 'Summon Storm', '召唤风暴', 'サモン・ストーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：支付800基本分才能发动。从手卡把1只6星以下的风属性怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。从手卡把1只4星以下的风属性怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(70781052, 'Summoned Skull', '恶魔的召唤', 'デーモンの召喚', 'Normal Monster', 'Fiend', 'DARK', 6, 2500, 1200, '使用黑暗力量，迷惑人心的恶魔。在恶魔族中以相当强大的力量著称。'),
(423585, 'Summoner Monk', '召唤僧', '召喚僧サモンプリースト', 'Effect Monster', 'Spellcaster', 'DARK', 4, 800, 1600, '①：这张卡召唤·反转召唤的场合发动。这张卡变成守备表示。 ②：只要这张卡在怪兽区域存在，这张卡不能解放。 ③：1回合1次，从手卡丢弃1张魔法卡才能发动。从卡组把1只4星怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(14644902, 'Summoner of Illusions', '幻想召唤师', '幻想召喚師', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 3, 800, 900, '①：这张卡反转的场合发动。这张卡以外的自己场上1只怪兽解放，从额外卡组把1只融合怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(79816536, 'Summoner''s Art', '召唤师之技法', '召喚師のスキル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只5星以上的通常怪兽加入手卡。'),
(61650133, 'Summoning Curse', '召唤的诅咒', '召喚の呪詛', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己的结束阶段支付500基本分。或者不支付500基本分让这张卡破坏。这张卡在场上存在的场合怪兽特殊召唤成功时，那些怪兽的控制者选择1张手卡从游戏中除外。'),
(52838896, 'Summoning Swarm', '一齐蜂起', '一斉蜂起', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是昆虫族怪兽不能从额外卡组特殊召唤。 ①：以最多有对方场上的怪兽数量的自己墓地的4星以下的「蜂军」怪兽为对象才能发动。那些怪兽特殊召唤。'),
(39823987, 'Sun Dragon Inti', '太阳龙 因蒂', '太陽龍インティ', 'Synchro Monster', 'Dragon', 'LIGHT', 8, 3000, 2800, '「赤蚁」＋调整以外的怪兽1只以上 ①：这张卡被战斗破坏送去墓地的场合发动。把让这张卡破坏的怪兽破坏，给与对方那个攻击力一半数值的伤害。 ②：场上的这张卡被破坏的下个回合的准备阶段，以自己墓地1只「月影龙 基利亚」为对象才能发动。那只怪兽特殊召唤。'),
(77432167, 'Sun God Unification', '太阳神合一', '太陽神合一', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的①②的效果在同一连锁上不能发动，自己场上有原本卡名是「太阳神之翼神龙」的怪兽存在的场合，这张卡在盖放的回合也能发动。 ①：自己·对方的主要阶段，把基本分支付到变成100基本分才能发动。选自己场上1只特殊召唤的「太阳神之翼神龙」，那个攻击力·守备力上升支付的数值。 ②：1回合1次，把自己场上1只「太阳神之翼神龙」解放才能发动。自己基本分回复那个攻击力的数值。'),
(54340229, 'Sunavalon Bloom', '圣天树之开花', '聖天樹の開花', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，自己场上有连接4以上的植物族连接怪兽存在的场合，对方场上的全部表侧表示怪兽的效果无效化。 ②：自己的植物族连接怪兽进行战斗的伤害计算时才能发动。那只怪兽的攻击力直到回合结束时上升那所连接区的怪兽的攻击力的合计数值。'),
(7984540, 'Sunavalon Daphne', '圣天树之月桂精', '聖天樹の月桂精', 'Link Monster', 'Plant', 'EARTH', NULL, NULL, NULL, '植物族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ②：把自己场上1只怪兽解放，以「圣天树之月桂精」以外的自己墓地2只植物族连接怪兽为对象才能发动。那些怪兽回到额外卡组。'),
(39880350, 'Sunavalon Dryades', '圣天树之精灵', '聖天樹の精霊', 'Link Monster', 'Plant', 'EARTH', NULL, NULL, NULL, '包含「圣天树」连接怪兽的植物族怪兽2只 ①：这张卡不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ②：自己因战斗·效果受到伤害的场合才能发动。自己基本分回复那个数值，从额外卡组把1只「圣蔓」怪兽特殊召唤。这个效果1回合可以使用最多2次。'),
(65285459, 'Sunavalon Dryanome', '圣天树之大精灵', '聖天樹の大精霊', 'Link Monster', 'Plant', 'EARTH', NULL, NULL, NULL, '植物族怪兽2只以上 ①：这张卡不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ②：1回合最多3次，自己因战斗·效果受到伤害的场合才能发动。自己基本分回复那个数值，从额外卡组把1只「圣蔓」怪兽特殊召唤。 ③：1回合1次，这所连接区的怪兽成为攻击对象时才能发动。攻击无效，那只自己怪兽的位置向其他的自己的主要怪兽区域移动。'),
(93896655, 'Sunavalon Dryas', '圣天树之幼精', '聖天樹の幼精', 'Link Monster', 'Plant', 'EARTH', NULL, NULL, NULL, '4星以下的植物族怪兽1只 ①：这张卡用「圣种之地灵」为素材在额外怪兽区域连接召唤的场合才能发动。从卡组把1张「圣蔓」魔法·陷阱卡加入手卡。 ②：这张卡不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ③：1回合1次，自己因战斗·效果受到伤害的场合才能发动。自己基本分回复那个数值，从额外卡组把1只「圣蔓」怪兽特殊召唤。'),
(92770064, 'Sunavalon Dryatrentiay', '圣天树之大母神', '聖天樹の大母神', 'Link Monster', 'Plant', 'EARTH', NULL, NULL, NULL, '连接怪兽2只以上 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「圣天树」魔法·陷阱卡加入手卡。 ②：这张卡不会被对方的效果破坏，不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ③：1回合1次，把这张卡所连接区1只自己的连接怪兽解放才能发动。选最多有那个连接标记数量的对方场上的卡破坏。'),
(44478599, 'Sunavalon Melias', '圣天树之灰树精', '聖天樹の灰樹精', 'Link Monster', 'Plant', 'EARTH', NULL, NULL, NULL, '包含连接怪兽的植物族怪兽2只以上 ①：这张卡连接召唤成功的场合才能发动。从自己墓地选1只「圣种之地灵」特殊召唤。 ②：这张卡不会被作为攻击对象（自己场上只有被这个效果适用的怪兽存在的状态中对方的攻击变成对自己的直接攻击）。 ③：1回合1次，以这张卡所连接区1只自己的「圣蔓」连接怪兽为对象才能发动。这个回合，那只怪兽可以作出最多有自己场上的「圣天树」连接怪兽数量的攻击。'),
(10321588, 'Sunlight Unicorn', '日光独角兽', 'サンライト・ユニコーン', 'Effect Monster', 'Beast', 'LIGHT', 4, 1800, 1000, '1回合1次，自己的主要阶段时才能发动。把自己卡组最上面的卡翻开，那是装备魔法卡的场合加入手卡。不是的场合，回到自己卡组最下面。'),
(78360952, 'Sunlit Sentinel', '白昼的狙击手', '白昼のスナイパー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2300, 1500, '①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：盖放的这张卡被破坏送去墓地的场合，下个回合的准备阶段才能发动。这张卡特殊召唤。那之后，和这张卡相同纵列的对方的卡全部破坏。'),
(73837870, 'Sunny Pixie', '阳光妖精', 'サニー・ピクシー', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, 300, 400, '这张卡被光属性的同调怪兽的同调召唤使用送去墓地的场合，自己回复1000基本分。'),
(27520594, 'Sunseed Genius Loci', '圣种之地灵', '聖種の地霊', 'Normal Monster', 'Plant', 'EARTH', 1, NULL, 600, '千年仅1次可以从圣天树获得的种子，据说经过千年时间会成为那片土地的守护精灵。'),
(30013902, 'Sunseed Shadow', '圣种之影芽', '聖種の影芽', 'Effect Monster', 'Plant', 'EARTH', 1, NULL, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有植物族通常怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把墓地的这张卡除外，以连接状态而连接2以下的自己1只「圣天树」怪兽或者「圣蔓」怪兽为对象才能发动。从额外卡组把那1只同名怪兽效果无效特殊召唤。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。'),
(66407907, 'Sunseed Twin', '圣种之天双芽', '聖種の天双芽', 'Effect Monster', 'Plant', 'EARTH', 2, NULL, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「圣天树」连接怪兽存在，这张卡召唤·特殊召唤成功的场合，以自己墓地1只4星以下的植物族通常怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡和自己场上1只连接怪兽除外才能发动。自己墓地有同名植物族连接怪兽2只以上存在的场合，选那之内的1只特殊召唤。'),
(42510430, 'Sunset Beat', '日落律动', 'サンセット・ビート', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示怪兽变成里侧守备表示的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：自己场上的反转怪兽反转的场合，以那之内的1只为对象才能发动（伤害步骤也能发动）。给与对方那只怪兽的等级×200伤害。'),
(70473293, 'Sunvine Cross Breed', '圣蔓之交配', '聖蔓の交配', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：把自己场上1只连接怪兽解放，以那只怪兽以外的自己墓地1只植物族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(28168762, 'Sunvine Gardna', '圣蔓之守卫者', '聖蔓の守護者', 'Link Monster', 'Plant', 'EARTH', NULL, 600, NULL, '植物族通常怪兽1只 ①：自己场上的「圣天树」连接怪兽因效果从场上离开的场合发动。这张卡破坏。 ②：和「圣天树」连接怪兽成为连接状态的这张卡在和对方怪兽进行战斗的攻击宣言时才能发动。那次战斗发生的对自己的战斗伤害变成一半。 ③：这张卡被战斗破坏时才能发动。那次伤害步骤结束后战斗阶段结束。'),
(65563871, 'Sunvine Healer', '圣蔓之治愈者', '聖蔓の癒し手', 'Link Monster', 'Plant', 'EARTH', NULL, 600, NULL, '植物族通常怪兽1只 ①：自己场上的「圣天树」连接怪兽因效果从场上离开的场合发动。这张卡破坏。 ②：这张卡特殊召唤成功的场合，以场上1只「圣天树」连接怪兽为对象才能发动。自己回复那个连接标记数量×300基本分。 ③：自己的植物族连接怪兽给与对方战斗伤害时才能发动。自己回复600基本分。'),
(53618293, 'Sunvine Maiden', '圣蔓之少女', '聖蔓の乙女', 'Effect Monster', 'Plant', 'EARTH', 1, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：从额外卡组特殊召唤的自己场上的植物族怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时才能发动。这张卡从手卡特殊召唤，那个效果无效。 ②：只要这张卡在怪兽区域存在，自己场上的「圣天树」魔法·陷阱卡以及「圣蔓」魔法·陷阱卡不会成为对方的效果的对象。'),
(27946124, 'Sunvine Shrine', '圣蔓之社', '聖蔓の社', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有「圣天树」连接怪兽存在的场合，把1张手卡送去墓地才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，自己不是植物族怪兽不能从额外卡组特殊召唤。 ②：1回合1次，可以发动。从自己墓地选1只4星以下的植物族通常怪兽特殊召唤。 ③：对方结束阶段，把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己墓地1张永续陷阱卡为对象才能发动。那张卡在自己的魔法与陷阱区域盖放。'),
(53286626, 'Sunvine Sowing', '圣蔓之播种', '聖蔓の播種', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「圣种」怪兽特殊召唤，自己受到1000伤害。自己场上没有「圣天树」连接怪兽存在的场合，这个效果不是「圣种之地灵」不能特殊召唤。这张卡的发动后，直到回合结束时自己不是植物族怪兽不能从额外卡组特殊召唤。 ②：自己场上的植物族连接怪兽被战斗或者对方的效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(91557476, 'Sunvine Thrasher', '圣蔓之剑士', '聖蔓の剣士', 'Link Monster', 'Plant', 'EARTH', NULL, 800, NULL, '植物族通常怪兽1只 ①：自己场上的「圣天树」连接怪兽因效果从场上离开的场合发动。这张卡破坏。 ②：这张卡特殊召唤成功的场合，以场上1只「圣天树」连接怪兽为对象才能发动。这张卡的攻击力上升那个连接标记数量×800。 ③：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽在作为连接怪兽所连接区的自己场上效果无效特殊召唤。'),
(78552773, 'Supay', '苏帕伊', 'スーパイ', 'Tuner Monster', 'Fiend', 'EARTH', 1, 300, 100, '①：这张卡被效果从场上送去墓地时才能发动。从卡组把1只「太阳之神官」特殊召唤。这个效果特殊召唤的怪兽攻击力变成2倍，这个回合的结束阶段回到持有者手卡。'),
(17315396, 'Supay, Duskwalker', '死神官－苏帕伊', '死神官－スーパイ', 'Effect Monster', 'Spellcaster', 'EARTH', 5, 2200, 1900, '这个卡名的效果1回合只能使用1次。 ①：把这张卡以外的1张手卡丢弃才能发动。这张卡从手卡守备表示特殊召唤。那之后，可以从手卡·卡组把1只「苏帕伊」特殊召唤。这个效果发动的回合，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(16780318, 'Super All In!', '超胜负！', '超勝負！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己场上1只同调怪兽回到持有者的额外卡组，从自己墓地选4只「花札卫」怪兽特殊召唤。那之后，自己从卡组抽1张，给双方确认。那是「花札卫」怪兽的场合，可以把那只怪兽无视召唤条件特殊召唤。不是的场合，自己场上的怪兽全部破坏，自己基本分变成一半。 ②：这张卡被「花札卫」怪兽的效果送去墓地的回合的结束阶段才能发动。从自己墓地选1张魔法·陷阱卡加入手卡。'),
(84769941, 'Super Anti-Kaiju War Machine Mecha-Dogoran', '对坏兽用决战兵器 超级机械多哥兰', '対壊獣用決戦兵器スーパーメカドゴラン', 'Effect Monster', 'Machine', 'LIGHT', 8, -1, 2000, '这张卡不能通常召唤。对方场上有「坏兽」怪兽存在的场合可以特殊召唤。 ①：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ②：1回合1次，把自己·对方场上2个坏兽指示物取除才能发动。从自己的手卡·墓地选1只「坏兽」怪兽当作装备卡使用给这张卡装备。 ③：这张卡的攻击力上升这张卡的效果装备的「坏兽」怪兽的原本攻击力数值。'),
(29913783, 'Super Anti-Kaiju War Machine Mecha-Thunder-King', '对坏兽用决战兵器 机械雷霆王', '対壊獣用決戦兵器メカサンダー・キング', 'Effect Monster', 'Machine', 'LIGHT', 9, 2200, 2100, '这个卡名的④的效果在决斗中只能使用1次。 ①：双方的主要阶段把这张卡从手卡丢弃才能发动。选原本持有者是对方的自己场上1只「坏兽」怪兽除外。那之后，可以从自己墓地选1只怪兽特殊召唤。 ②：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ③：场上的这张卡不受其他的「坏兽」卡的效果影响，不会被和「坏兽」怪兽的战斗破坏。 ④：自己结束阶段才能发动。这张卡从墓地特殊召唤。'),
(77754169, 'Super Armored Robot Armed Black Iron "C"', '超装甲兵器机器人 黑铁G', '超装甲兵器ロボ ブラックアイアンG', 'Effect Monster', 'Insect', 'EARTH', 8, 2400, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地有昆虫族同名怪兽3只存在的场合，以那之内的任意数量为对象才能发动。这张卡从手卡特殊召唤。那之后，作为对象的怪兽当作装备卡使用给这张卡装备。 ②：把这张卡的效果装备的1张怪兽卡送去墓地才能发动。持有送去墓地的那张卡的攻击力以上的攻击力的对方场上的怪兽全部破坏。'),
(41516133, 'Super B.E.S. Metal Slave', '超巨大战舰 金属仆从', '超巨大戦艦 メタル・スレイブ', 'Effect Monster', 'Machine', 'DARK', 11, 3100, 3100, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡·卡组把最多5只10星以下的「巨大战舰」怪兽送去墓地才能发动（同名卡最多1张）。这张卡从手卡特殊召唤。那之后，为这个效果发动而送去墓地的数量的指示物给这张卡放置。 ②：自己·对方回合，把这张卡1个指示物取除，以包含自己场上的「巨大战舰」怪兽的场上2张表侧表示卡为对象才能发动（同一连锁上最多1次）。那些卡破坏。'),
(85520851, 'Super Conductor Tyranno', '超传导恐兽', '超伝導恐獣', 'Effect Monster', 'Dinosaur', 'LIGHT', 8, 3300, 1400, '①：1回合1次，把自己场上1只怪兽解放才能发动。给与对方1000伤害。这个效果发动的回合，这张卡不能攻击宣言。'),
(86804246, 'Super Crashbug', '超级漏洞人', 'スーパーバグマン', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, 3000, '这张卡不能通常召唤。把自己墓地存在的「漏洞人X」「漏洞人Y」「漏洞人Z」从游戏中除外的场合可以表侧守备表示特殊召唤。只要这张卡在场上表侧表示存在，场上表侧攻击表示存在的全部怪兽的攻击力·守备力交换。「超级漏洞人」在场上只能有1只表侧表示存在。'),
(45496268, 'Super Defense Robot Elephan', '超级防卫机器人·象斗士', 'SDロボ・エレファン', 'Effect Monster', 'Machine', 'EARTH', 8, 1400, 2500, '这张卡召唤成功时，可以从手卡把1只名字带有「超级防卫机器人」的怪兽或者「轨道 7」特殊召唤。1回合1次，选择自己场上1只名字带有「超级防卫机器人」的怪兽或者「轨道 7」才能发动。选择的怪兽的等级直到结束阶段时变成8星。此外，把这张卡作为超量召唤的素材的场合，不是机械族怪兽的超量召唤不能使用。'),
(8091563, 'Super Defense Robot Lio', '超级防卫机器人·狮斗士', 'SDロボ・ライオ', 'Effect Monster', 'Machine', 'EARTH', 4, 1200, 1600, '这张卡召唤成功时，可以从手卡把1只名字带有「超级防卫机器人」的怪兽或者「轨道 7」特殊召唤。此外，1回合1次，从自己墓地有名字带有「超级防卫机器人」的怪兽或者「轨道 7」1只加入自己手卡时，可以把那只怪兽从手卡特殊召唤。'),
(71880877, 'Super Defense Robot Monki', '超级防卫机器人·猴斗士', 'SDロボ・モンキ', 'Effect Monster', 'Machine', 'EARTH', 3, 800, 1200, '这张卡召唤成功时，可以从手卡把1只名字带有「超级防卫机器人」的怪兽或者「轨道 7」特殊召唤。此外，1回合1次，把自己墓地1只机械族怪兽从游戏中除外才能发动。从自己墓地选择1只名字带有「超级防卫机器人」的怪兽或者「轨道 7」加入手卡。'),
(26120084, 'Super Double Summon', '特殊二重召唤', 'スペシャル・デュアル・サモン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只二重怪兽，变成再度召唤的状态。这个回合的结束阶段时，选择的二重怪兽回到手卡。'),
(52481437, 'Super Express Bullet Train', '弹丸特急 子弹快列', '弾丸特急バレット・ライナー', 'Effect Monster', 'Machine', 'EARTH', 10, 3000, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上的怪兽只有机械族·地属性怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击宣言之际，自己必须把这张卡以外的自己场上2张卡送去墓地。 ③：这张卡被送去墓地的回合的结束阶段，以「弹丸特急 子弹快车」以外的自己墓地1只机械族怪兽为对象才能发动。那只怪兽加入手卡。'),
(11050415, 'Super Hippo Carnival', '超河马嘉年华', '超カバーカーニバル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从自己的手卡·卡组·墓地选1只「娱乐伙伴 探寻河马」特殊召唤。那之后，可以在自己场上把「河马衍生物」（兽族·地·1星·攻/守0）尽可能特殊召唤。这衍生物不能解放。只要「河马衍生物」在怪兽区域存在，自己不能从额外卡组把怪兽特殊召唤。这个效果把「河马衍生物」特殊召唤的场合，直到回合结束时对方不能把「河马衍生物」以外的怪兽作为攻击对象。');